	zip.Describe("github.com/hanzoai/cloud/apps/captable POST /v1/captable/shares", zip.Doc{
		Description: "Issues a share certificate to a stakeholder.\n\nThe certificate id must be UNIQUE within the company — a duplicate is refused\n409, not silently merged — and both the stakeholder and the share class must\nbelong to this company, so an id from another tenant is a 400 rather than a\ncross-company issuance.",
		Fields: map[string]string{
			"captableCreated.id":                  "ID is the created row's id.",
			"captableCreated.message":             "Message is the human sentence the cap table wrote, e.g. \"Share issued\".",
			"captableCreated.success":             "Success is true when the row was written.",
			"captableShareIn.boardApprovalDate":   "BoardApprovalDate is when the board approved the issuance, YYYY-MM-DD.",
			"captableShareIn.capitalContribution": "CapitalContribution is cash paid for the shares. Optional.",
			"captableShareIn.certificateId":       "CertificateID is the certificate number. It must be UNIQUE within the company; reusing one is refused 409.",
			"captableShareIn.cliffYears":          "CliffYears is how long before ANY of the grant vests. A whole number; 0 for no cliff.",
			"captableShareIn.companyLegends":      "CompanyLegends are the restrictive legends printed on the certificate.\n\nA LIST, and it must be sent as one: the bundle substitutes an EMPTY list for\nanything that is not an array, so a single string would be accepted and\nsilently discarded — the certificate issued with no legends and nothing\nreporting it.",
			"captableShareIn.debtCancelled":       "DebtCancelled is debt forgiven as consideration. Optional.",
			"captableShareIn.ipContribution":      "IPContribution is intellectual property assigned as consideration, valued in the company's currency. Optional.",
			"captableShareIn.issueDate":           "IssueDate is when the shares were issued, YYYY-MM-DD.",
			"captableShareIn.otherContributions":  "OtherContributions is any other consideration, valued in the company's currency. Optional.",
			"captableShareIn.pricePerShare":       "PricePerShare is what was paid per share. Optional.",
			"captableShareIn.quantity":            "Quantity is how many shares to issue. A whole number above 0.",
			"captableShareIn.rule144Date":         "Rule144Date is when the Rule 144 holding period starts, YYYY-MM-DD. Optional.",
			"captableShareIn.shareClassId":        "ShareClassID is the class being issued. It must name a class of THIS company.",
			"captableShareIn.stakeholderId":       "StakeholderID is who receives the shares. It must name a stakeholder of THIS company.",
			"captableShareIn.status":              "Status is ACTIVE, DRAFT, SIGNED or PENDING.",
			"captableShareIn.vestingStartDate":    "VestingStartDate is when vesting begins, YYYY-MM-DD. Optional; defaults to the issue date.",
			"captableShareIn.vestingYears":        "VestingYears is the total vesting period. A whole number; 0 for fully vested at issue.",
		},
	})
	zip.Describe("github.com/hanzoai/cloud/apps/captable POST /v1/captable/shares/transfer", zip.Doc{
		Description: "Moves shares from one stakeholder to another.\n\nOmit `quantity` to transfer the whole certificate, which REASSIGNS it and mints\nno new share. Send a quantity below the amount held to SPLIT it — the source\ncertificate keeps the remainder, and a split additionally requires\n`certificateId` for the new certificate, which must be unique in the company.\nA quantity outside 1..held is refused, so a transfer can never over-issue.\n\nBoth outcomes answer 200: a transfer records a movement between holders and\nmints no security of its own, which is why this is not a 201 the way an\ninvestment is.",
		Fields: map[string]string{
			"captableShareTransfer.certificateId":   "CertificateID names the NEW certificate a partial transfer issues, and is\nrequired for one — a partial transfer without it is refused 400. It is unused\nby a full transfer, which reassigns the existing certificate.\n\nIt must be unique within the company; reusing one is refused 409. Declaring\nit is not optional in the way the tag suggests: omitting this field from the\nGo type would leave `quantity` accepted and every PARTIAL transfer answering\n\"certificateId is required\" with no way for a caller to supply it — the\nsilent-drop failure this whole conversion was blocked on, one field wide.",
			"captableShareTransfer.quantity":        "Quantity is how many shares to move. OPTIONAL, and its absence is not zero:\nomitted or null transfers the WHOLE certificate. A value outside 1..held is\nrefused, so a partial transfer can never over-issue.\n\nA full transfer REASSIGNS the certificate and mints no new one; a partial\ntransfer splits it and answers with the new share's id. That is the fact a\ncaller needs from the answer, not from this comment.",
			"captableShareTransfer.shareId":         "ShareID is the certificate being transferred. Required, and it must name a\nshare in the caller org's own company — a share id from another tenant\nresolves to not-found rather than to another company's certificate.",
			"captableShareTransfer.toStakeholderId": "ToStakeholderID is who receives them. Required, and it must reference a\nstakeholder of the SAME company; one that does not is refused 400 rather\nthan creating a dangling holder.",
			"captableTransferred.message":           "Message is the human sentence the cap table wrote, e.g. \"Share transferred\".",
			"captableTransferred.newShareId":        "NewShareID names the certificate a PARTIAL transfer created. It is null on a\nfull transfer, which reassigns the existing certificate instead of splitting\nit — so null here means \"no new certificate\", never \"the transfer failed\".",
			"captableTransferred.success":           "Success is true when the transfer was applied.",
			"captableTransferred.transferred":       "Transferred is how many shares moved.",
		},
	})
